package com.securebiz.report.api;import com.securebiz.report.api.DashboardDtos.DashboardResponse;import com.securebiz.report.service.DashboardService;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import java.nio.charset.StandardCharsets;import java.time.*;
@RestController@RequestMapping("/api/v1/reports")public class DashboardController{private final DashboardService service;public DashboardController(DashboardService service){this.service=service;}@GetMapping("/dashboard")DashboardResponse dashboard(@RequestParam@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to){return service.dashboard(from,to);}@GetMapping(value="/dashboard.csv",produces="text/csv")ResponseEntity<byte[]>export(@RequestParam@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to){var report=service.export(from,to);return ResponseEntity.ok().contentType(new MediaType("text","csv",StandardCharsets.UTF_8)).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+report.filename()+"\"").body(report.content());}}
